    };
    applyTheme();

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => { if (settings.appearance === 'system') applyTheme(); };
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  // Determine active background class
  // UPDATED: Now applies globally (except splash), not just in game
  const activeBackgroundClass = useMemo(() => {
    if (screen === 'splash') return 'bg-stone-50 dark:bg-stone-900';

    const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
    return bg ? bg.class : 'bg-paper dark:bg-stone-900';
  }, [screen, selectedBackgroundId]);

  // Handlers
  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playTap();
    setSelectedDifficulty(diff);
    setScreen('levels');
    setDirection(1);
  };

  const handleLevelSelect = (levelId: number) => {
    sounds.playTap();
    setSelectedLevel(levelId);
    setScreen('game');
    sounds.playLevelEnter();
  };

  const handleEarnPoints = (amount: number) => {
      const newTotal = Storage.addPoints(amount);
      setPoints(newTotal);
  };

  const handlePurchase = (item: {id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string}) => {
      if (points >= item.cost) {
          setPurchaseCandidate(item);
      } else {
          setShowNotEnoughPoints(true);
      }
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;

      let success = false;
      if (purchaseCandidate.type === 'bg') {
          success = Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
              Storage.selectBackground(purchaseCandidate.id);
              setSelectedBackgroundId(purchaseCandidate.id);
          }
      } else if (purchaseCandidate.type === 'num') {
          success = Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedNumberColors(Storage.getPurchasedNumberColors());
              Storage.selectNumberColor(purchaseCandidate.id);
              setSelectedNumberColorId(purchaseCandidate.id);
          }
      } else if (purchaseCandidate.type === 'skill') {
          success = Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedSkills(Storage.getPurchasedSkills());
              setEnabledSkills(Storage.getEnabledSkills());
          }
      } else if (purchaseCandidate.type === 'sound') {
          success = Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost);
          if (success) {
              setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
              Storage.selectSoundPack(purchaseCandidate.id);
              setSelectedSoundPackId(purchaseCandidate.id);
          }
      }

      if (success) {
          setPoints(Storage.getPoints());
          sounds.playWin(); // Cha-ching sound
      }
      setPurchaseCandidate(null);
  };

  const handleUnlockPack = (packType: 2 | 3) => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, packType);

      if (points >= cost) {
          if (packType === 2) {
             const success = Storage.unlockPack2(selectedDifficulty, cost);
             if (success) {
                 setPoints(Storage.getPoints());
                 setUnlockedPacks2(Storage.getUnlockedPacks2());
                 sounds.playWin();
             }
          } else {
             const success = Storage.unlockPack3(selectedDifficulty, cost);
             if (success) {
                 setPoints(Storage.getPoints());
                 setUnlockedPacks3(Storage.getUnlockedPacks3());
                 sounds.playWin();
             }
          }
      } else {
          setShowNotEnoughPoints(true);
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      setPaymentOffer(offer);
  };

  const confirmPayment = () => {
      if (!paymentOffer) return;

      const newPoints = Storage.addPoints(paymentOffer.diamonds);
      setPoints(newPoints);

      // Handle Includes
      if (offerContains(paymentOffer, 'Auto')) {
           Storage.purchaseSkill('skill-auto', 0);
      }
      if (offerContains(paymentOffer, 'Scan')) {
           Storage.purchaseSkill('skill-scan', 0);
      }
      if (offerContains(paymentOffer, 'Reveal')) {
           Storage.purchaseSkill('skill-reveal', 0);
      }

      if (paymentOffer.id === 'starter_pack') {
           Storage.purchaseNumberColor('num-purple', 0);
           Storage.purchaseNumberColor('num-teal', 0);
           Storage.setStarterPackPurchased();
           setStarterPackPurchased(true);
      }

      if (paymentOffer.type === 'bundle') {
          Storage.purchaseBundle(paymentOffer.id);
          setPurchasedBundles(Storage.getPurchasedBundles());

          if (paymentOffer.id === 'bundle_cosmetic') {
              // Unlock all static backgrounds
              ALL_BACKGROUNDS.forEach(bg => Storage.purchaseBackground(bg.id, 0));
          }
          if (paymentOffer.id === 'bundle_pro') {
              // Unlock Diamond Number
              Storage.purchaseNumberColor('num-rgb', 0);
              // Unlock All Skills
              SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
          }
      }

      // Refresh State
      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());

      setPaymentOffer(null);
  };

  const offerContains = (offer: DiamondOffer, text: string) => {
      return offer.includes?.some(i => i.includes(text));
  };

  const handleWatchAd = () => {
      setIsWatchingAd(true);
      setTimeout(() => {
          setIsWatchingAd(false);
          const newPoints = Storage.addPoints(50);
          setPoints(newPoints);
          sounds.playWin();
      }, 3000);
  };

  const handleClaimBonus = () => {
      const now = Date.now();
      if (now >= nextBonusClaimTime) {
          const newPoints = Storage.addPoints(10);
          setPoints(newPoints);

          // Set next claim time to 4 hours from now
          const nextTime = now + (4 * 60 * 60 * 1000);
          Storage.setNextBonusClaimTime(nextTime);
          setNextBonusClaimTime(nextTime);

          sounds.playWin();
      }
  };

  const activeNumberColor = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  return (
    <div className={`w-full h-full relative overflow-hidden transition-colors duration-500 ${activeBackgroundClass}`}>
      <AnimatePresence custom={direction}>
        {screen === 'splash' && (
             <motion.div key="splash" className="absolute inset-0 z-50" exit={{ opacity: 0 }} transition={{ duration: 0.5 }}>
                <SplashScreen />
             </motion.div>
        )}

        {screen === 'difficulty' && (
            <motion.div 
                key="difficulty"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0, x: -50 }}
                transition={{ duration: 0.25 }}
            >
                <DifficultyScreen 
                    points={points}
                    onDifficultySelect={handleDifficultySelect}
                    onOpenSettings={() => setShowSettings(true)}
                    onOpenStore={() => { setDirection(1); setScreen('store'); }}
                    onOpenDiamondShop={() => { setDirection(1); setScreen('diamondShop'); }}
                    onOpenStats={() => { setDirection(1); setScreen('stats'); }}
                    onClaimBonus={handleClaimBonus}
                    nextBonusClaimTime={nextBonusClaimTime}
                />
            </motion.div>
        )}

        {screen === 'levels' && selectedDifficulty && (
            <motion.div 
                key="levels"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0, x: 50 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -50 }}
                transition={{ duration: 0.25 }}
            >
                <LevelsScreen 
                    difficulty={selectedDifficulty} 
                    points={points}
                    unlockedPacks2={unlockedPacks2}
                    unlockedPacks3={unlockedPacks3}
                    onBack={() => { setDirection(-1); setScreen('difficulty'); }}
                    onLevelSelect={handleLevelSelect}
                    onOpenSettings={() => setShowSettings(true)}
                    onUnlockPack2={() => handleUnlockPack(2)}
                    onUnlockPack3={() => handleUnlockPack(3)}
                />
            </motion.div>
        )}

        {screen === 'game' && selectedDifficulty && selectedLevel && (
            <motion.div 
                key="game"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 1.05 }}
                transition={{ duration: 0.25 }}
            >
                <SudokuGame 
                    difficulty={selectedDifficulty}
                    levelId={selectedLevel}
                    onBack={() => { setDirection(-1); setScreen('levels'); }}
                    onReturnToMenu={() => { setDirection(-1); setScreen('difficulty'); }}
                    onComplete={() => {}}
                    onSettingsOpen={() => setShowSettings(true)}
                    settings={settings}
                    onEarnPoints={handleEarnPoints}
                    currentPoints={points}
                    isSettingsOpen={showSettings}
                    backgroundClass={activeBackgroundClass}
                    numberColor={activeNumberColor}
                    purchasedSkills={enabledSkills}
                />
            </motion.div>
        )}

        {screen === 'store' && (
            <motion.div 
                key="store"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0, x: 50 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -50 }}
                transition={{ duration: 0.25 }}
            >
                <StoreScreen 
                    points={points}
                    onBack={() => { setDirection(-1); setScreen('difficulty'); }}
                    purchasedSkills={purchasedSkills}
                    enabledSkills={enabledSkills}
                    purchasedBackgrounds={purchasedBackgrounds}
                    purchasedNumberColors={purchasedNumberColors}
                    purchasedSoundPacks={purchasedSoundPacks}
                    selectedBackgroundId={selectedBackgroundId}
                    selectedNumberColorId={selectedNumberColorId}
                    selectedSoundPackId={selectedSoundPackId}
                    onPurchase={(item, type) => handlePurchase({ ...item, type })}
                    onSelectBackground={(id) => { Storage.selectBackground(id); setSelectedBackgroundId(id); }}
                    onSelectNumberColor={(id) => { Storage.selectNumberColor(id); setSelectedNumberColorId(id); }}
                    onSelectSoundPack={(id) => { Storage.selectSoundPack(id); setSelectedSoundPackId(id); }}
                    onToggleSkill={(id) => { const enabled = Storage.toggleSkillEnabled(id); setEnabledSkills(enabled); }}
                />
            </motion.div>
        )}

        {screen === 'diamondShop' && (
            <motion.div 
                key="diamondShop"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0, x: 50 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -50 }}
                transition={{ duration: 0.25 }}
            >
                <DiamondShopScreen 
                    points={points}
                    onBack={() => { setDirection(-1); setScreen('difficulty'); }}
                    onWatchAd={handleWatchAd}
                    onBuyOffer={handleBuyOffer}
                    starterPackPurchased={starterPackPurchased}
                    purchasedBundles={purchasedBundles}
                />
            </motion.div>
        )}

        {screen === 'stats' && (
            <motion.div 
                key="stats"
                className="absolute inset-0 w-full h-full flex flex-col"
                initial={{ opacity: 0, x: 50 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -50 }}
                transition={{ duration: 0.25 }}
            >
                <StatsScreen onBack={() => { setDirection(-1); setScreen('difficulty'); }} />
            </motion.div>
        )}

      </AnimatePresence>

      {/* Modals */}
      {showSettings && (
          <SettingsModal 
              settings={settings}
              onToggle={(key) => {
                  const newSettings = { ...settings, [key]: !settings[key] };
                  setSettings(newSettings);
                  Storage.saveSettings(newSettings);
                  sounds.playTap();
              }}
              onSetAppearance={(val) => {
                  const newSettings = { ...settings, appearance: val };
                  setSettings(newSettings);
                  Storage.saveSettings(newSettings);
                  sounds.playTap();
              }}
              onReset={() => {
                  if (confirm("Reset all progress? This cannot be undone.")) {
                      Storage.resetAllData();
                      window.location.reload();
                  }
              }}
              onClose={() => setShowSettings(false)}
              onAddDevPoints={() => {
                  const newPoints = Storage.addPoints(5000);
                  setPoints(newPoints);
              }}
          />
      )}

      {purchaseCandidate && (
          <PurchaseModal 
              item={purchaseCandidate}
              onConfirm={confirmPurchase}
              onCancel={() => setPurchaseCandidate(null)}
          />
      )}

      {paymentOffer && (
          <PaymentModal 
              offer={paymentOffer}
              onComplete={confirmPayment}
              onCancel={() => setPaymentOffer(null)}
          />
      )}

      {showNotEnoughPoints && (
          <NotEnoughPointsModal 
              onClose={() => setShowNotEnoughPoints(false)}
              onGetMore={() => { 
                  setShowNotEnoughPoints(false); 
                  setScreen('diamondShop'); 
                  setDirection(1); 
              }}
              onGoPlay={() => {
                  setShowNotEnoughPoints(false);
                  if (screen !== 'game' && screen !== 'levels' && screen !== 'difficulty') {
                      setScreen('difficulty');
                      setDirection(-1);
                  }
              }}
          />
      )}

      {isWatchingAd && <AdOverlay />}

    </div>
  );
}

import React, { useState } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        const isPurchased = purchasedSoundPacks.includes(pack.id);
        const isSelected = selectedSoundPackId === pack.id;

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else if (!isSelected) {
            onSelectSoundPack(pack.id);
        }
    };

    const handleSkillInteraction = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);
        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            sounds.playClick();
            onToggleSkill(skill.id);
        }
    };

    // Shared Price Footer component for grid items
    const ItemFooter = ({ isPurchased, isSelected, cost }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-6 bg-white/80 dark:bg-stone-800/80 backdrop-blur-sm border-t border-t-border flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[13px] font-bold text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                </div>
            );
        }
        return null;
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
             {/* Locked Header */}
             <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Store</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Personalize</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm border border-t-border relative z-30">
                      <span className="text-sm font-bold text-t-primary">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-10 pt-2">

                      {/* SKILLS SECTION - Redesigned List View (Compact) */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Skills</h2>
                          <div className="flex flex-col gap-3">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);

                                  return (
                                      <button 
                                          key={skill.id}
                                          onClick={(e) => handleSkillInteraction(e, skill)}
                                          className={`w-full p-3 rounded-3xl shadow-sm border border-t-border flex items-center gap-3.5 text-left active:scale-[0.98] transition-all bg-t-surface relative overflow-hidden group`}
                                      >
                                          {/* Icon Box - Smaller */}
                                          <div className={`w-14 h-14 rounded-xl flex items-center justify-center shrink-0 ${skill.bgClass} transition-transform group-active:scale-95`}>
                                              <skill.icon className={`w-7 h-7 ${skill.class}`} />
                                          </div>

                                          {/* Text Content */}
                                          <div className="flex-1 min-w-0 py-0.5">
                                              <h3 className="text-lg font-bold text-t-primary leading-tight mb-1">{skill.name}</h3>
                                              <p className="text-xs font-medium text-t-secondary leading-snug line-clamp-2">{skill.description}</p>
                                          </div>

                                          {/* Action Area */}
                                          <div className="shrink-0 pl-1">
                                              {isPurchased ? (
                                                   // Toggle UI
                                                   <div className={`w-12 h-7 rounded-full p-1 transition-colors duration-300 ease-out ${isEnabled ? 'bg-stone-600 dark:bg-stone-400' : 'bg-stone-300 dark:bg-stone-700'}`}>
                                                       <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-5' : 'translate-x-0'}`} />
                                                   </div>
                                              ) : (
                                                   // Price UI
                                                   <div className="flex flex-col items-center justify-center bg-stone-100 dark:bg-stone-800 border border-stone-200 dark:border-stone-700 px-3 py-2 rounded-xl min-w-[60px]">
                                                       <span className="text-sm font-bold text-t-primary leading-none">{skill.cost}</span>
                                                       <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current mt-0.5" />
                                                   </div>
                                              )}
                                          </div>
                                      </button>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1.5">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-[3px] ${isSelected ? 'border-stone-600 dark:border-stone-400 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-2">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1.5">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-white dark:bg-stone-800 border-[3px] ${isSelected ? 'border-stone-600 dark:border-stone-400 scale-105 z-10' : 'border-t-border'}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;

                              return (
                                  <div key={pack.id} className="flex flex-col items-center gap-1.5 relative">
                                      <button 
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all border-[3px] ${isSelected ? 'border-stone-600 dark:border-stone-400 scale-105 z-10' : 'border-t-border bg-t-surface active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <div className={`absolute inset-0 bg-gradient-to-br ${pack.colorClass} opacity-20 dark:opacity-30`} />
                                              <pack.icon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>
                                      <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1.5">
