import React, { useEffect, useState } from 'react';
import './App.css';
import { Routes, Route } from 'react-router-dom';
import { Splash, Game, Difficulty, Levels, Stats, Store } from './pages';
import { useLocalStorage } from './hooks/useLocalStorage';
import { STATIC_BACKGROUNDS } from './constants';

function App() {
  const [background, setBackground] = useLocalStorage('background', 'default');
  const [activeBackgroundClass, setActiveBackgroundClass] = useState<string>('');
  const [overlayOpacity, setOverlayOpacity] = useState<string>('0');
  const [screen, setScreen] = useState('');
  const [isGradient, setIsGradient] = useState(false);

  useEffect(() => {
    const defaultBackgroundClass = 'bg-paper dark:bg-stone-900';
    const selectedBackground = STATIC_BACKGROUNDS.find((bg) => bg.id === background);

    if (background === 'splash') {
      setActiveBackgroundClass('bg-splash');
    } else if (selectedBackground) {
      setActiveBackgroundClass(selectedBackground.class);
    } else {
      setActiveBackgroundClass(defaultBackgroundClass);
    }
  }, [background]);

  useEffect(() => {
    setIsGradient(activeBackgroundClass.includes('gradient'));
  }, [activeBackgroundClass]);

  useEffect(() => {
    let opacity = '0';
    if (isGradient && screen === 'game') {
      opacity = '0.5';
    }

    setOverlayOpacity(opacity);
  }, [screen, isGradient]);

  useEffect(() => {
    document.documentElement.style.setProperty('--overlay-opacity', overlayOpacity);
  }, [overlayOpacity]);

  return (
    <div className={`App ${activeBackgroundClass}`}>
      <Routes>
        <Route path="/" element={<Splash setScreen={setScreen} setBackground={setBackground} />} />
        <Route path="/game" element={<Game setScreen={setScreen} />} />
        <Route path="/difficulty" element={<Difficulty setScreen={setScreen} />} />
        <Route path="/levels" element={<Levels setScreen={setScreen} />} />
        <Route path="/stats" element={<Stats setScreen={setScreen} />} />
        <Route path="/store" element={<Store setScreen={setScreen} />} />
      </Routes>
    </div>
  );
}

export default App;
```

