                          {/* Get More - Reimagined: Polished Aluminum / High-End Silver */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} 
                            // Silver Gradient: White -> Slate 100 -> Slate 300
                            style={{ background: 'linear-gradient(135deg, #ffffff 0%, #f1f5f9 50%, #cbd5e1 100%)' }}
                            className="w-full p-4 text-slate-800 rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08),inset_0_1px_0_rgba(255,255,255,1)] flex items-center justify-center gap-2 active:scale-95 transition-all relative overflow-hidden border border-slate-200/60"
