};

import React from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    timer: number;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    onAutoFill,
    onScan,
    onReveal,
    timer
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    // Removed borders from base container styles
    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800'
            : 'bg-t-surface-sec dark:bg-stone-800/50';

    const revealTimeLeft = Math.max(0, 60 - timer);
    const isRevealLocked = revealTimeLeft > 0;

    return (
        <div className="flex justify-between w-full relative">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onReveal(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(revealUses > 0 && !revealingCell && !isRevealLocked)}`}
                        disabled={revealUses <= 0 || !!revealingCell || isRevealLocked}
                    >
                    {/* Removed border class */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(revealUses > 0 && !isRevealLocked)}`}>
                        {isRevealLocked ? (
                            <div className="w-5 h-5 flex items-center justify-center">
                                <span className="text-[10px] font-bold text-stone-400 font-mono leading-none">{revealTimeLeft}s</span>
                            </div>
                        ) : (
                            <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        )}

                        {/* Removed border-2 border-t-surface */}
                        <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold leading-none ${revealUses > 0 && !isRevealLocked ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600'}`}>
                                {revealUses > 0 ? revealUses : '+'}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onScan(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}
                        disabled={scanUses <= 0 || scanCooldown || isScanning}
                    >
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(scanUses > 0 && !scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        {scanUses > 0 && (
                            <div className={`absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full flex items-center justify-center text-sm font-bold leading-none ${scanUses > 0 ? 'bg-blue-600 text-white' : 'hidden'}`}>
                                {scanUses}
                            </div>
                        )}
                    </div>
                    <span className="text-sm font-medium">Scan</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onAutoFill(e); }} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    {/* Removed borders and rings */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 dark:bg-amber-900/30' 
                        : 'bg-t-surface-sec dark:bg-stone-800/50'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-sm font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                {/* Removed borders */}
                <div className={`p-3 rounded-full shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 dark:bg-blue-900/40' 
                    : 'bg-white dark:bg-stone-800'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-sm font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Erase</span>
            </button>
        </div>
    );
};

import React from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // Logic for Levels & Unlocking
    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    let totalVisibleLevels = 100;
    if (isPack2Unlocked) totalVisibleLevels = 200;
    if (isPack3Unlocked) totalVisibleLevels = 300;

    const allLevels = Array.from({ length: totalVisibleLevels }, (_, i) => i + 1);

    // Count completed levels for specific ranges to drive unlock cards
    const completedRange1 = Storage.getCompletedCountInRange(difficulty, 1, 100);
    const completedRange2 = Storage.getCompletedCountInRange(difficulty, 101, 200);

    // Global Best for Header
    let globalBest = Infinity;
    allLevels.forEach(l => {
        const p = Storage.getLevelProgress(difficulty, l);
        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
            globalBest = p.bestTime;
        }
    });
    const hasGlobalBest = globalBest !== Infinity;

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                    <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                    {hasGlobalBest && (
                        <div className="flex flex-col items-center animate-fade-in mt-1">
                            <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                        </div>
                    )}
                </div>

                <button onClick={() => { sounds.playClick(); onOpenSettings(); }} className="p-2 rounded-full hover:bg-stone-200 -mr-2 text-t-icon relative z-30">
                    <Icons.Settings className="w-6 h-6 text-t-icon" />
                </button>
            </div>

            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                <div className="w-full max-w-md grid grid-cols-5 gap-3 pt-2">
                    {allLevels.map((lvl) => {
                            const progress = Storage.getLevelProgress(difficulty, lvl);
                            const isCompleted = progress?.status === 'completed';
                            const isInProgress = progress?.status === 'in-progress';
                            const bestTime = progress?.bestTime;
                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                            // Removed 'border' and 'border-t-border'. Replaced 'border-2' for in-progress with 'ring-2'.
                            return (
                                <button key={lvl} onClick={() => onLevelSelect(lvl)} className={`aspect-square rounded-xl relative transition-all active:scale-90 ${isCompleted ? 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5' : isInProgress ? 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary' : 'bg-t-surface shadow-sm hover:shadow-md text-t-primary'}`}>
                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                    {bestTime ? (
                                        isGlobalBest ? (
                                            <>
                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                </div>
                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                </div>
                                            </>
                                        ) : (
                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                <span className="text-[10px] text-t-secondary font-bold tracking-tight block">{formatTimeShort(bestTime)}</span>
                                            </div>
                                        )
                                    ) : null}
                                </button>
                            );
                    })}
                </div>

                {/* Unlock Card Logic - Chained */}
                {!isPack2Unlocked && (
                    <UnlockCard 
                        startLevel={101}
                        endLevel={200}
                        completedCount={completedRange1}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 2)}
                        onUnlock={onUnlockPack2}
                    />
                )}

                {isPack2Unlocked && !isPack3Unlocked && (
                        <UnlockCard 
                        startLevel={201}
                        endLevel={300}
                        completedCount={completedRange2}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 3)}
                        onUnlock={onUnlockPack3}
                    />
                )}

                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { Icons } from './Icons';

interface UnlockCardProps {
    startLevel: number;
    endLevel: number;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

export const UnlockCard: React.FC<UnlockCardProps> = ({ startLevel, endLevel, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);
    const [showUnlockUI, setShowUnlockUI] = useState(false);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                    setShowUnlockUI(false); // Reset UI state
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            const duration = 2500; // Slower duration
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = progress; // Linear easing

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                    if (rawPercent === 100) {
                        // Wait a moment after hitting 100% before showing the unlock button
                        setTimeout(() => {
                            setShowUnlockUI(true);
                        }, 500);
                    }
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!showUnlockUI) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!showUnlockUI}
                // Removed borders
                className={`w-full h-32 rounded-[1.5rem] relative overflow-hidden transition-all duration-500 ease-out group ${
                    showUnlockUI 
                        ? 'bg-gradient-to-b from-white to-blue-50/50 dark:from-stone-800 dark:to-stone-900 shadow-lg active:scale-[0.98] cursor-pointer' 
                        : 'bg-stone-200 dark:bg-stone-800/80 cursor-default'
                }`}
            >
                {/* Background Decor for Unlock State */}
                {showUnlockUI && (
                    <div className="absolute inset-0 opacity-100 pointer-events-none">
                        <div className="absolute -top-12 -right-12 w-32 h-32 bg-blue-400/10 rounded-full blur-2xl"></div>
                        <div className="absolute -bottom-12 -left-12 w-32 h-32 bg-indigo-400/10 rounded-full blur-2xl"></div>
                    </div>
                )}

                {/* Content Container */}
                <div className="absolute inset-0 flex items-center justify-center px-6">
                    {showUnlockUI ? (
                        <div className="flex flex-row items-center justify-between w-full animate-fade-in relative z-10 gap-2">

                             {/* Left Side: Info & CTA */}
                             <div className="flex flex-col items-start gap-1.5">
                                 {/* Header Pill - Removed border */}
                                 <div className="flex items-center gap-1.5 px-2.5 py-1 bg-white dark:bg-stone-800 rounded-full shadow-sm">
                                    <Icons.LockOpen className="w-3 h-3 text-blue-500" />
                                    <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest pt-0.5">
                                        Levels {startLevel}-{endLevel}
                                    </span>
                                 </div>
                                 {/* Flashing CTA */}
                                 <span className="text-[10px] font-bold text-blue-500 uppercase tracking-widest pl-1 animate-pulse ml-0.5">
                                     Tap to Unlock
                                 </span>
                             </div>

                             {/* Right Side: Price */}
                             <div className="flex items-center gap-2">
                                <span className="text-5xl font-bold text-stone-900 dark:text-white leading-none">
                                    {cost}
                                </span>
                                <Icons.Diamond className="w-8 h-8 text-blue-500 fill-current drop-shadow-sm" />
                             </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full gap-5">
                            {/* Left Side: Lock Icon */}
