                            const isPurchased = purchasedBundles.includes(offer.id);

                            return (
                                <button 
                                    key={offer.id}
                                    onClick={() => !isPurchased && onBuyOffer(offer)}
                                    disabled={isPurchased}
                                    className={`w-full relative overflow-hidden rounded-[1.25rem] transition-all text-left group
                                        ${offer.gradientClass ? offer.gradientClass : 'bg-t-surface border border-t-border'}
                                        ${isPurchased ? 'shadow-none opacity-50 grayscale cursor-not-allowed' : 'active:scale-95 shadow-sm'}
                                    `}
                                >
                                    {/* Shimmer for Pro Bundle */}
                                    {offer.id === 'bundle_pro' && !isPurchased && (
                                         <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent z-0 animate-shimmer pointer-events-none" />
                                    )}

