                                             <div className={`px-3 py-1.5 rounded-lg text-xs font-bold shadow-sm min-w-[80px] text-center min-h-[28px] flex items-center justify-center ${isPurchased ? 'bg-stone-400 text-white' : 'btn-premium-silver'}`}>
                                                 {isPurchased ? 'OWNED' : offer.priceLabel}
                                             </div>
                                        </div>
