                        >
                            Restore Purchases
                        </button>
                    </div>
                </div>
                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { Logo } from '../ui/Logo';
import { sounds } from '../../utils/sound';
import { getDifficultyPoints, DIFFICULTY_DESCRIPTIONS } from '../../utils/constants';

interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
}

// Internal Hook for Counting Animation
const useAnimatedCounter = (target: number, duration: number = 500) => {
    const [count, setCount] = useState(0);

    useEffect(() => {
        let startTime: number | null = null;
        let animationFrameId: number;

        // Reset start value to 0 on target change to trigger animation
        setCount(0);

        const animate = (currentTime: number) => {
            if (!startTime) startTime = currentTime;
            const progress = Math.min((currentTime - startTime) / duration, 1);

            // Cubic Ease Out
            const ease = 1 - Math.pow(1 - progress, 3);

            setCount(Math.floor(target * ease));

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };

        animationFrameId = requestAnimationFrame(animate);

        return () => {
            if (animationFrameId) cancelAnimationFrame(animationFrameId);
        };
    }, [target, duration]);

    return count;
};

// Sub-component for individual cards
const DifficultyCard: React.FC<{
    diff: Difficulty;
    index: number;
    onSelect: (diff: Difficulty) => void;
    activeInfo: Difficulty | null;
    onInfoToggle: (diff: Difficulty) => void;
    isClosing: boolean;
    description: string;
}> = ({ diff, index, onSelect, activeInfo, onInfoToggle, isClosing, description }) => {

    // Data Loading
    const completed = Storage.getCompletedCount(diff, 300);
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    const isPack3Unlocked = Storage.isPack3Unlocked(diff);

    let maxLevels = 100;
    if (isPack2Unlocked) maxLevels = 200;
    if (isPack3Unlocked) maxLevels = 300;

    const diffPoints = getDifficultyPoints(diff);

    // Animation Logic
    const row = Math.floor(index / 2);
    const delay = 100 + (row * 50);
    const isInfoActive = activeInfo === diff;
    const isLeftColumn = index % 2 === 0;

    // State to track if entry animation is done
    // We remove the animation class after it finishes to remove the 'transform' property,
    // which prevents stacking context issues on iOS that clip tooltips.
    const [animating, setAnimating] = useState(true);
    useEffect(() => {
        const t = setTimeout(() => {
            setAnimating(false);
        }, delay + 600); // delay + animation duration (400ms) + buffer
        return () => clearTimeout(t);
    }, [delay]);

    // Z-Index Logic: 
    // Upper rows must have higher z-index than lower rows so tooltips (which go down) overlap correctly.
    // Row 0 (SuperEasy/Easy): Base 30
    // Row 1 (Normal/Hard): Base 20
    // Row 2 (Intense/Impossible): Base 10
    // Active Card: 100 (Always on top)
    const baseZIndex = 30 - (row * 10);
    const finalZIndex = isInfoActive ? 100 : baseZIndex;

    // Use animated counter hook
    const animatedCompleted = useAnimatedCounter(completed, 500);

    // Calculate width percentage based on animated value for synced bar/text
    const progressPercent = Math.min((animatedCompleted / maxLevels) * 100, 100);

    return (
        <button 
            onClick={() => onSelect(diff)} 
            style={{ 
                animationDelay: `${delay}ms`,
                zIndex: finalZIndex 
            }}
            className={`bg-t-surface p-3 rounded-2xl shadow-sm flex flex-col justify-between active:scale-95 transition-transform text-left relative group min-h-[100px] overflow-visible ${animating ? 'opacity-0 animate-slide-in-down' : 'opacity-100'}`}
        >
            {/* Header: Title & Points */}
            <div className="w-full flex justify-between items-center mb-1">
                <span className="text-lg font-semibold text-t-primary leading-none tracking-tight">{diff}</span>
                <div className="flex items-center gap-1 shrink-0">
                    <span className="text-sm font-bold text-t-primary">+{diffPoints}</span>
                    <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                </div>
            </div>

            {/* Middle: Info & Progress Numbers */}
            <div className="w-full flex justify-between items-end mb-1.5 mt-auto">
                {/* Info Icon */}
                <div className="relative z-50" onClick={(e) => e.stopPropagation()}>
                    <div 
                        role="button"
                        onClick={() => onInfoToggle(diff)}
                        className={`w-[24px] h-[24px] rounded-full border flex items-center justify-center transition-colors cursor-pointer ${
                            isInfoActive 
                            ? 'bg-stone-200 border-stone-400 dark:bg-stone-600 dark:border-stone-400' 
                            : 'border-stone-300 dark:border-stone-600 bg-t-surface hover:bg-stone-100 dark:hover:bg-stone-700'
                        }`}
                    >
                        <Icons.Info className={`w-3.5 h-3.5 ${isInfoActive ? 'text-stone-700 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500'}`} />
                    </div>

                    {/* Tooltip */}
                    {isInfoActive && (
                        <div 
                            className={`absolute top-full mt-2 w-44 z-[60] cursor-default ${
                                isLeftColumn 
                                    ? '-left-2 origin-top-left' // Shift left 8px
                                    : '-right-2 origin-top-right' // Shift right 8px
                            } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            {/* Speech Bubble Container */}
                            <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed border border-stone-400 dark:border-stone-500">
                                {description}
                                {/* Arrow - Attached seamlessly */}
                                {/* Shifted to 14px to clear the 12px corner radius of rounded-xl */}
                                <div className={`absolute -top-[6px] w-3 h-3 bg-white border-t border-l border-stone-400 dark:border-stone-500 transform rotate-45 ${
                                    isLeftColumn ? 'left-[14px]' : 'right-[14px]'
                                }`}></div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Progress Numbers (Animated) - SIZE REDUCED to text-sm font-bold */}
                <span className="text-sm text-t-primary font-bold tracking-wide font-sans leading-none">
                    {animatedCompleted} / {maxLevels}
                </span>
            </div>

            {/* Bottom: Progress Bar (Animated) */}
            <div className="w-full h-1.5 bg-t-surface-sec rounded-full overflow-hidden">
                <div 
                    className="h-full bg-loading-blue" 
                    style={{ 
                        width: `${progressPercent}%`,
                        // Use CSS transition for extra smoothness if state updates are coarse
                        transition: 'width 0.1s linear' 
                    }}
                ></div>
            </div>
        </button>
    );
};

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    // Track index for cycling descriptions per difficulty
    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            const diff = nextBonusClaimTime - now;
            const h = Math.floor(diff / (1000 * 60 * 60));
            const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((diff % (1000 * 60)) / 1000);

            // Pad with leading zeros
            const hStr = h.toString().padStart(2, '0');
            const mStr = m.toString().padStart(2, '0');
            const sStr = s.toString().padStart(2, '0');

            setTimeLeft(`${hStr}:${mStr}:${sStr}`);
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            // Cycle to the next description after closing
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150); // Matches tooltip-exit duration
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Scrollable Content - No Fixed Header */}
             <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">

                  {/* Hero Section - Static (Always on screen) */}
                  <div className="flex flex-col items-center mt-[70px] mb-6">
                      <Logo size={70} className="mb-4 drop-shadow-xl" />
                      <h1 className="text-3xl font-semibold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Difficulty Header - Stagger Step 1 (50ms) */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-semibold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid - Stagger Steps 2, 3, 4 (Row based) */}
                  <div className="w-full max-w-md grid grid-cols-2 gap-3 mb-8 shrink-0">
                      {Object.values(Difficulty).map((diff, index) => {
                          // Get cycling description logic here to pass down
                          const descriptions = DIFFICULTY_DESCRIPTIONS[diff];
                          const currentIndex = infoIndices[diff] || 0;
                          const description = descriptions[currentIndex % descriptions.length];

                          return (
                              <DifficultyCard 
                                  key={diff}
                                  diff={diff}
                                  index={index}
                                  onSelect={onDifficultySelect}
                                  activeInfo={activeInfo}
                                  onInfoToggle={handleInfoToggle}
                                  isClosing={isClosing && activeInfo === diff}
                                  description={description}
                              />
                          );
                      })}
                  </div>

                  {/* Footer Actions - Stagger Steps 5, 6 */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More - 250ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down" 
                        style={{ animationDelay: '250ms' }}
                      >
                          {/* Store - Gold Gradient (#E8BA6E -> #B78B4D) */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStore(); }} 
                            style={{ background: 'linear-gradient(135deg, #E8BA6E 0%, #B78B4D 100%)' }}
                            className="w-full p-4 text-[#3f2e18] rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition relative hover:shadow-md"
                          >
                              <Icons.Store className="w-5 h-5" /> <span className="font-semibold tracking-wide">Store</span>
                          </button>

                          {/* Get More - Reimagined: Polished Aluminum / High-End Silver */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} 
                            // Silver Gradient: White -> Slate 100 -> Slate 300
                            style={{ background: 'linear-gradient(135deg, #ffffff 0%, #f1f5f9 50%, #cbd5e1 100%)' }}
                            className="w-full p-4 text-slate-800 rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08),inset_0_1px_0_rgba(255,255,255,1)] flex items-center justify-center gap-2 active:scale-95 transition-all relative overflow-hidden"
                          >
                              {/* Soft Blue Glow at bottom (Diamond reflection) */}
                              <div className="absolute bottom-0 inset-x-0 h-12 bg-gradient-to-t from-blue-100/30 to-transparent pointer-events-none" />

                              {/* Sharp Shine Animation */}
                              <div className="absolute inset-0 -translate-x-full animate-[shimmer_4s_infinite] bg-gradient-to-r from-transparent via-white/80 to-transparent skew-x-[-20deg] pointer-events-none" />

                              <span className="font-bold tracking-wide relative z-10 text-slate-700">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10 drop-shadow-sm" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus - 300ms */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down"
                        style={{ animationDelay: '300ms' }}
                      >
                          {/* Stats - Blue Gradient (#B8D3F5 -> #79A6E3) */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStats(); }} 
                            style={{ background: 'linear-gradient(135deg, #B8D3F5 0%, #79A6E3 100%)' }}
                            className="w-full p-4 text-[#102a43] rounded-2xl shadow-sm flex items-center justify-center gap-2 active:scale-95 transition hover:shadow-md"
                          >
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-semibold tracking-wide">Stats</span>
                          </button>

                          {/* Daily Bonus - Green Gradient (#B8DBBE -> #8CB794) */}
                          <button 
                              onClick={(e) => { e.stopPropagation(); onClaimBonus(); }}
                              disabled={!!timeLeft}
                              style={!timeLeft ? { background: 'linear-gradient(135deg, #B8DBBE 0%, #8CB794 100%)' } : undefined}
                              className={`w-full p-4 rounded-2xl shadow-sm flex items-center justify-center gap-2 transition overflow-hidden relative ${
                                  !!timeLeft 
                                  ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed' 
                                  : 'text-[#163c20] hover:shadow-md active:scale-95'
                              }`}
                          >
                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-5 h-5" />
                                      <span className="font-semibold tabular-nums">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-semibold tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>

                  {/* Utility Row (Points + Settings) - Moved to Bottom */}
                  <div 
                    className="w-full max-w-md flex items-center justify-center gap-3 mt-6 mb-2 opacity-0 animate-slide-in-down" 
                    style={{ animationDelay: '350ms' }}
                  >
                       {/* Points - Compact */}
                      <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm">
                          <span className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5">{points}</span>
                          <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                      </div>

                      {/* Settings - Compact */}
                      <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenSettings(); }} className="p-1.5 bg-t-surface rounded-full shadow-sm hover:bg-stone-100 dark:hover:bg-stone-800 transition active:scale-95 text-t-icon">
                          <Icons.Settings className="w-5 h-5" />
                      </button>
                  </div>

                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

