                    >
                        <Icons.Info className={`w-4 h-4 transition-colors ${isInfoActive ? 'text-stone-800 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500 hover:text-stone-600 dark:hover:text-stone-400'}`} />
                    </div>

                    {/* Tooltip */}
                    {isInfoActive && (
                        <div 
                            className={`absolute top-full mt-2 w-44 z-[60] cursor-default ${
                                // Smart tooltip positioning based on card position if needed, 
                                // but simpler to stick to one side for flex items if alignment varies.
                                // Defaulting to right alignment logic mostly works, but lets keep existing logic
                                // based on "index" passed in, though strict columns might vary.
                                // For simplicity in flex layout, left column logic still basically applies 
                                // to the first item in a wrapped row.
                                isLeftColumn 
                                    ? '-left-2 origin-top-left' 
                                    : '-right-2 origin-top-right'
                            } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed border border-stone-400 dark:border-stone-500 shadow-lg">
