interface WinModalProps {
    difficulty: Difficulty;
    levelId: number;
    timer: number;
    points: number;
    isGeneratingReplay: boolean;
    replayUrl: string | null;
    showReplay: boolean;
    generateReplayEnabled: boolean;
    onReplay: (e: React.MouseEvent) => void;
    onShareReplay: () => void;
    onCloseReplay: () => void;
    onGenerateReplay: () => void;
    onBack: (e: React.MouseEvent) => void;
    onReturnToMenu: (e: React.MouseEvent) => void;
}

const useCounter = (target: number, duration: number = 800, start: boolean = false) => {
    const [count, setCount] = useState(0);
    useEffect(() => {
        if (!start) {
            setCount(0);
            return;
        }
        let startTime: number;
        let animationFrame: number;

        const animate = (time: number) => {
            if (!startTime) startTime = time;
            const progress = Math.min((time - startTime) / duration, 1);
            // Cubic ease out
            const ease = 1 - Math.pow(1 - progress, 3); 
            setCount(Math.floor(target * ease));

            if (progress < 1) {
                animationFrame = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };
        animationFrame = requestAnimationFrame(animate);
        return () => cancelAnimationFrame(animationFrame);
    }, [target, duration, start]);
    return count;
};

const ReplayPlayer = ({ src, onShare, onClose }: { src: string, onShare: () => void, onClose: () => void }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isPlaying, setIsPlaying] = useState(true);
    const [isMuted, setIsMuted] = useState(false);

    const togglePlay = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        if (videoRef.current) {
            if (isPlaying) {
                videoRef.current.pause();
                setIsPlaying(false);
            } else {
                videoRef.current.play();
                setIsPlaying(true);
            }
        }
    };

    const toggleMute = (e?: React.MouseEvent) => {
        e?.stopPropagation();
        if (videoRef.current) {
            videoRef.current.muted = !isMuted;
            setIsMuted(!isMuted);
        }
    };

    return (
        <div className="fixed inset-0 bg-black z-[110] flex flex-col items-center justify-center animate-fade-in">
             {/* Main Video Container */}
             <div 
                className="relative w-full max-w-lg aspect-square bg-stone-900 shadow-2xl overflow-hidden rounded-none sm:rounded-2xl group cursor-pointer"
                onClick={togglePlay}
             >
                  <video 
                      ref={videoRef}
                      src={src} 
                      autoPlay 
                      loop 
                      playsInline 
                      className="w-full h-full object-cover"
                  />

                  {/* Only show center play button when paused, otherwise keep video clean */}
                  {!isPlaying && (
                      <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[1px] animate-fade-in pointer-events-none">
                          <div className="w-20 h-20 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center border border-white/30 shadow-lg">
                              <Icons.Play className="w-10 h-10 text-white fill-current ml-1" />
                          </div>
                      </div>
                  )}
             </div>

             {/* Unified Control Bar */}
             <div className="absolute bottom-10 left-0 right-0 flex items-center justify-center gap-2 px-4 pointer-events-none flex-wrap sm:flex-nowrap">
                 {/* Share/Save - Primary Action */}
                 <button 
                     onClick={onShare}
                     className="h-14 px-6 bg-white text-black rounded-full font-bold shadow-xl active:scale-95 transition flex items-center gap-2 pointer-events-auto"
                 >
                     <Icons.Share className="w-5 h-5 text-blue-500" /> Share/Save
                 </button>

                 <div className="flex gap-2">
                     {/* Pause/Play */}
                     <button 
                        onClick={togglePlay}
                        className="w-14 h-14 bg-stone-800 text-white rounded-full shadow-xl active:scale-95 transition flex items-center justify-center pointer-events-auto"
                     >
                         {isPlaying ? <Icons.Pause className="w-6 h-6 fill-current" /> : <Icons.Play className="w-6 h-6 fill-current ml-1" />}
                     </button>

                     {/* Mute/Unmute */}
                     <button 
                        onClick={toggleMute}
                        className="w-14 h-14 bg-stone-800 text-white rounded-full shadow-xl active:scale-95 transition flex items-center justify-center pointer-events-auto"
                     >
                         {isMuted ? <Icons.Mute className="w-6 h-6" /> : <Icons.Sound className="w-6 h-6" />}
                     </button>

                     {/* Close */}
                     <button 
                         onClick={onClose}
                         className="w-14 h-14 bg-stone-800 text-white rounded-full shadow-xl active:scale-95 transition flex items-center justify-center pointer-events-auto"
                     >
                         <Icons.Close className="w-6 h-6" />
                     </button>
                 </div>
             </div>
        </div>
    );
};

export const WinModal: React.FC<WinModalProps> = ({
    difficulty,
    levelId,
    timer,
    points,
    isGeneratingReplay,
    replayUrl,
    showReplay,
    generateReplayEnabled,
    onReplay,
    onShareReplay,
    onCloseReplay,
    onGenerateReplay,
    onBack,
    onReturnToMenu
}) => {
    const [step, setStep] = useState(0);
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // Animation Sequencing
    useEffect(() => {
        // Step 1: Checkmark (Immediate)
        const t1 = setTimeout(() => setStep(1), 100);
        // Step 2: Difficulty/Level Header
        const t2 = setTimeout(() => setStep(2), 500);
        // Step 3: "Solved!" Title
        const t3 = setTimeout(() => setStep(3), 800);
        // Step 4: Points Earned
        const t4 = setTimeout(() => setStep(4), 1400);
        // Step 5: Time
        const t5 = setTimeout(() => setStep(5), 2000);
        // Step 6: Actions
        const t6 = setTimeout(() => setStep(6), 2800);

        return () => {
            clearTimeout(t1);
            clearTimeout(t2);
            clearTimeout(t3);
            clearTimeout(t4);
            clearTimeout(t5);
            clearTimeout(t6);
        };
    }, []);

    // Confetti Effect
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        resize();
        window.addEventListener('resize', resize);

        // Premium Palette: Gold, Silver, Soft Blue, White
        const colors = ['#FCD34D', '#E2E8F0', '#93C5FD', '#FFFFFF'];
        const particleCount = 150;

        interface Particle {
            x: number;
            y: number;
            vx: number;
            vy: number;
            color: string;
            size: number;
            rotation: number;
            rotationSpeed: number;
            opacity: number;
        }

        const particles: Particle[] = [];
        const cx = canvas.width / 2;
        const cy = canvas.height / 2;

        for (let i = 0; i < particleCount; i++) {
            // Burst Physics
            const angle = Math.random() * Math.PI * 2;
            const velocity = Math.random() * 15 + 8;

            particles.push({
                x: cx,
                y: cy,
                vx: Math.cos(angle) * velocity * (Math.random() * 0.8 + 0.2),
                vy: Math.sin(angle) * velocity * (Math.random() * 0.8 + 0.2) - 6, // Initial upward pop
                color: colors[Math.floor(Math.random() * colors.length)],
                size: Math.random() * 8 + 6,
                rotation: Math.random() * 360,
                rotationSpeed: (Math.random() - 0.5) * 12,
                opacity: 1
            });
        }

        let animationId: number;

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            let active = false;

            particles.forEach(p => {
                // Physics Update
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.35; // Gravity
                p.vx *= 0.95; // Friction
                p.vy *= 0.95;
                p.rotation += p.rotationSpeed;
                p.opacity -= 0.006; // Slow fade

                if (p.opacity > 0) {
                    active = true;
                    ctx.save();
                    ctx.globalAlpha = p.opacity;
                    ctx.translate(p.x, p.y);
                    ctx.rotate((p.rotation * Math.PI) / 180);
                    ctx.fillStyle = p.color;
                    // Draw confetti square
                    ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
                    ctx.restore();
                }
            });

            if (active) {
                animationId = requestAnimationFrame(animate);
            }
        };

        animate();

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationId);
        };
    }, []);

    const animatedPoints = useCounter(points, 800, step >= 4);
    const animatedTimeSeconds = useCounter(timer, 800, step >= 5);

    const formatTime = (seconds: number) => {
        const total = Math.floor(seconds);
        const mins = Math.floor(total / 60);
        const secs = total % 60;
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    };

    if (showReplay && replayUrl) {
        return <ReplayPlayer src={replayUrl} onShare={onShareReplay} onClose={onCloseReplay} />;
    }

    return (
        <div className="fixed inset-0 bg-green-500/50 backdrop-blur-sm z-[100] flex flex-col items-center justify-center text-white animate-fade-in">
            {/* Confetti Canvas - Behind Modal */}
            <canvas ref={canvasRef} className="absolute inset-0 pointer-events-none z-0" />

            <div className="bg-white dark:bg-stone-800 text-stone-800 dark:text-t-primary p-8 rounded-3xl shadow-2xl w-80 text-center relative overflow-hidden transform transition-all z-10">

                {/* Step 1: Checkmark Icon */}
                <div 
                    className={`w-20 h-20 bg-green-100 dark:bg-green-900/50 rounded-full flex items-center justify-center mx-auto mb-6 text-green-500 dark:text-green-400 relative z-10 transition-all duration-500 cubic-bezier(0.34, 1.56, 0.64, 1) ${step >= 1 ? 'scale-100 opacity-100' : 'scale-0 opacity-0'}`}
                >
                    <Icons.Check className="w-10 h-10" />
                </div>

                {/* Step 2: Difficulty Header */}
                <div 
                    className={`flex flex-col gap-0.5 mb-2 relative z-10 transition-all duration-500 ${step >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}
                >
                    <div className="text-[10px] font-bold text-stone-400 dark:text-stone-500 uppercase tracking-widest">{difficulty} &bull; Level {levelId}</div>
                </div>

                {/* Step 3: Solved Title (Letter by Letter) */}
                <div className="mb-8 relative z-10 h-10">
                    <div className="flex justify-center items-center">
                        {['S','o','l','v','e','d','!'].map((char, i) => (
                            <span 
                                key={i}
                                className={`text-3xl font-bold text-stone-800 dark:text-white leading-tight inline-block transition-all duration-300`}
                                style={{ 
                                    transitionDelay: `${i * 40}ms`,
                                    opacity: step >= 3 ? 1 : 0,
                                    transform: step >= 3 ? 'translateY(0) scale(1)' : 'translateY(10px) scale(0.5)'
                                }}
                            >
                                {char}
                            </span>
                        ))}
                    </div>
                </div>

                {/* Step 4: Earnings Group */}
                <div 
                    className={`flex flex-col gap-1 mb-6 relative z-10 transition-all duration-500 ${step >= 4 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}
                >
                    <p className="text-stone-500 dark:text-stone-400 text-xs font-bold uppercase tracking-widest">You Earned</p>
                    <div className="flex items-center justify-center gap-1.5 h-8">
                        <span className="text-3xl font-bold text-stone-800 dark:text-t-primary tabular-nums">+{animatedPoints}</span>
                        <Icons.Diamond className="w-6 h-6 text-blue-500 fill-current" />
                    </div>
                </div>

                {/* Step 5: Time Group */}
                <div 
                    className={`flex flex-col gap-0.5 mb-8 relative z-10 transition-all duration-500 ${step >= 5 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}
                >
                    <p className="text-stone-400 dark:text-stone-500 text-[10px] uppercase tracking-widest font-bold">Time</p>
                    <p className="text-2xl font-medium tabular-nums text-stone-800 dark:text-white leading-tight">{formatTime(animatedTimeSeconds)}</p>
                </div>

                {/* Step 6: Actions */}
                <div 
                    className={`relative z-10 space-y-3 transition-all duration-700 ${step >= 6 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}
                >
                    {/* Replay Button */}
                    {generateReplayEnabled && (
                        isGeneratingReplay ? (
                            <div className="w-full py-3.5 flex items-center justify-center gap-2 text-stone-500 font-bold animate-pulse bg-stone-50 dark:bg-stone-800/50 rounded-xl border border-dashed border-stone-200 dark:border-stone-700">
                                <Icons.Video className="w-5 h-5" /> Generating Replay...
                            </div>
                        ) : replayUrl ? (
                            <button 
                            onClick={onReplay}
                            className="w-full py-3.5 bg-blue-500 text-white rounded-xl font-bold shadow-lg shadow-blue-500/20 active:scale-95 transition flex items-center justify-center gap-2 hover:bg-blue-600 animate-pop"
                            >
                            <Icons.Video className="w-5 h-5" /> Watch Replay
                            </button>
                        ) : (
                            <button 
                            onClick={onGenerateReplay}
                            className="w-full py-3.5 bg-stone-100 text-stone-600 dark:bg-stone-700 dark:text-stone-300 rounded-xl font-bold shadow-sm active:scale-95 transition flex items-center justify-center gap-2 hover:bg-stone-200 dark:hover:bg-stone-600"
                            >
                            <Icons.Video className="w-5 h-5" /> Create Replay
                            </button>
                        )
                    )}

                    <div className="flex gap-3">
                         <button onClick={onBack} className="flex-1 py-3.5 bg-stone-800 text-white dark:bg-stone-100 dark:text-stone-900 rounded-xl font-bold hover:bg-stone-700 dark:hover:bg-stone-200 active:scale-95 transition shadow-lg">Levels</button>
                         <button onClick={onReturnToMenu} className="flex-1 py-3.5 bg-white text-stone-600 border border-stone-300 dark:bg-stone-800 dark:text-stone-300 dark:border-stone-600 rounded-xl font-bold hover:bg-stone-50 dark:hover:bg-stone-700 active:scale-95 transition">Menu</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    // Calculate the currently highlighted value based on active input or selected cell
    const highlightedValue = useMemo(() => {
        if (activeNumber !== null) return activeNumber;
        if (selectedCell) {
            return board[selectedCell[0]][selectedCell[1]].value;
        }
        return null;
    }, [activeNumber, selectedCell, board]);

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;

        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        // Check if cell matches highlighted value for background highlight
        let isSameValue = false;
        if (cell.value !== null && highlightedValue !== null) {
            isSameValue = cell.value === highlightedValue;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             bgClass = 'bg-red-200 animate-pulse '; 
        } else if (isError || isConflict) {
             bgClass = 'bg-red-50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isRelated) {
             bgClass = 'bg-stone-200/60 dark:bg-stone-100/50 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isSelected && (isError || isConflict || isMarkedWrong)) {
            classes += "ring-2 ring-inset ring-red-400 z-10 ";
        }

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isError || isConflict || isMarkedWrong) {
                classes += "font-medium text-red-500 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' // Make completion border more prominent
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div className="bg-t-board rounded-lg overflow-hidden relative flex-none shadow-lg border border-t-border" style={{ width: squareSize, height: squareSize, maxWidth: '500px', maxHeight: '500px' }}>

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;

                    return (
                        <div 
                            key={`${rIndex}-${cIndex}`} 
                            className={getCellClass(cell, rIndex, cIndex)} 
                            onClick={(e) => {
                                e.stopPropagation();
                                onCellClick(e, rIndex, cIndex);
                            }} 
                            style={{ fontSize: mainFontSize }}
                        >
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] relative z-10 ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none relative z-10">
                                {[1,2,3,4,5,6,7,8,9].map(n => {
                                    // BOLD NOTE LOGIC
                                    const isNoteActive = n === highlightedValue;
                                    const noteClass = cell.notes.includes(n) 
                                        ? (isNoteActive 
                                            ? 'text-stone-900 dark:text-stone-100 font-black scale-110 transition-transform' 
                                            : 'text-stone-500 font-medium')
                                        : 'invisible';

                                    return (
                                        <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                            <span className={noteClass}>{n}</span>
                                        </div>
                                    )
                                })}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>

            {/* Section/Board Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

