                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

import React, { useMemo } from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    // Calculate the currently highlighted value based on active input or selected cell
    const highlightedValue = useMemo(() => {
        if (activeNumber !== null) return activeNumber;
        if (selectedCell) {
            return board[selectedCell[0]][selectedCell[1]].value;
        }
        return null;
    }, [activeNumber, selectedCell, board]);

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;

        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        // Check if cell matches highlighted value for background highlight
        let isSameValue = false;
        if (cell.value !== null && highlightedValue !== null) {
            isSameValue = cell.value === highlightedValue;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             bgClass = 'bg-red-200 animate-pulse '; 
        } else if (isError || isConflict) {
             bgClass = 'bg-red-50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-200 '; 
        } else if (settings.highlight && isRelated) {
             bgClass = 'bg-stone-200/60 dark:bg-stone-100/50 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isSelected && (isError || isConflict || isMarkedWrong)) {
            classes += "ring-2 ring-inset ring-red-400 z-10 ";
        }

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isError || isConflict || isMarkedWrong) {
                classes += "font-medium text-red-500 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' // Make completion border more prominent
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div 
                className="bg-t-board rounded-lg overflow-hidden relative flex-none border-[3px] border-stone-900 shadow-lg" 
                style={{ 
                    width: squareSize, 
                    height: squareSize, 
                    maxWidth: '500px', 
                    maxHeight: '500px'
                }}
            >

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;

                    return (
                        <div 
                            key={`${rIndex}-${cIndex}`} 
                            className={getCellClass(cell, rIndex, cIndex)} 
                            onClick={(e) => {
                                e.stopPropagation();
                                onCellClick(e, rIndex, cIndex);
                            }} 
                            style={{ fontSize: mainFontSize }}
                        >
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] relative z-10 ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none relative z-10">
                                {[1,2,3,4,5,6,7,8,9].map(n => {
                                    // BOLD NOTE LOGIC
                                    const isNoteActive = n === highlightedValue;
                                    const noteClass = cell.notes.includes(n) 
                                        ? (isNoteActive 
                                            ? 'text-stone-900 dark:text-stone-100 font-black scale-110 transition-transform' 
                                            : 'text-stone-500 font-medium')
                                        : 'invisible';

                                    return (
                                        <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                            <span className={noteClass}>{n}</span>
                                        </div>
                                    )
                                })}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>

            {/* Section/Board Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

import React from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // Logic for Levels & Unlocking
    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    let totalVisibleLevels = 100;
    if (isPack2Unlocked) totalVisibleLevels = 200;
    if (isPack3Unlocked) totalVisibleLevels = 300;

    const allLevels = Array.from({ length: totalVisibleLevels }, (_, i) => i + 1);

    // Count completed levels for specific ranges to drive unlock cards
    const completedRange1 = Storage.getCompletedCountInRange(difficulty, 1, 100);
    const completedRange2 = Storage.getCompletedCountInRange(difficulty, 101, 200);

    // Global Best for Header
    let globalBest = Infinity;
    allLevels.forEach(l => {
        const p = Storage.getLevelProgress(difficulty, l);
        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
            globalBest = p.bestTime;
        }
    });
    const hasGlobalBest = globalBest !== Infinity;

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full active:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                    <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                    {hasGlobalBest && (
                        <div className="flex flex-col items-center animate-fade-in mt-1">
                            <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                        </div>
                    )}
                </div>

                <button onClick={() => { sounds.playClick(); onOpenSettings(); }} className="p-2 rounded-full active:bg-stone-200 -mr-2 text-t-icon relative z-30">
                    <Icons.Settings className="w-6 h-6 text-t-icon" />
                </button>
            </div>

            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                <div className="w-full max-w-md grid grid-cols-5 gap-3 pt-2">
                    {allLevels.map((lvl) => {
                            const progress = Storage.getLevelProgress(difficulty, lvl);
                            const isCompleted = progress?.status === 'completed';
                            const isInProgress = progress?.status === 'in-progress';
                            const bestTime = progress?.bestTime;
                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                            // Removed 'border' and 'border-t-border'. Replaced 'border-2' for in-progress with 'ring-2'.
                            return (
                                <button key={lvl} onClick={() => onLevelSelect(lvl)} className={`aspect-square rounded-xl relative transition-all active:scale-90 ${isCompleted ? 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5' : isInProgress ? 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary' : 'bg-t-surface shadow-sm hover:shadow-md text-t-primary'}`}>
                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                    {bestTime ? (
                                        isGlobalBest ? (
                                            <>
                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                </div>
                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                </div>
                                            </>
                                        ) : (
                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                <span className="text-[10px] text-t-secondary font-bold tracking-tight block">{formatTimeShort(bestTime)}</span>
                                            </div>
                                        )
                                    ) : null}
                                </button>
                            );
                    })}
                </div>

                {/* Unlock Card Logic - Chained */}
                {!isPack2Unlocked && (
                    <UnlockCard 
                        startLevel={101}
                        endLevel={200}
                        completedCount={completedRange1}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 2)}
                        onUnlock={onUnlockPack2}
                    />
                )}

                {isPack2Unlocked && !isPack3Unlocked && (
                        <UnlockCard 
                        startLevel={201}
                        endLevel={300}
                        completedCount={completedRange2}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 3)}
                        onUnlock={onUnlockPack3}
                    />
                )}

                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};

