// Internal Hook for Counting Animation
const useAnimatedCounter = (target: number, duration: number = 500) => {
    const [count, setCount] = useState(0);

    useEffect(() => {
        let startTime: number | null = null;
        let animationFrameId: number;

        // Reset start value to 0 on target change to trigger animation
        setCount(0);

        const animate = (currentTime: number) => {
            if (!startTime) startTime = currentTime;
            const progress = Math.min((currentTime - startTime) / duration, 1);

            // Cubic Ease Out
            const ease = 1 - Math.pow(1 - progress, 3); 

            setCount(Math.floor(target * ease));

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };

        animationFrameId = requestAnimationFrame(animate);

        return () => {
            if (animationFrameId) cancelAnimationFrame(animationFrameId);
        };
    }, [target, duration]);

    return count;
};

// Sub-component for individual cards
const DifficultyCard: React.FC<{
    diff: Difficulty;
    index: number;
    onSelect: (diff: Difficulty) => void;
    activeInfo: Difficulty | null;
    onInfoToggle: (diff: Difficulty) => void;
    isClosing: boolean;
    description: string;
    isPyramidTop?: boolean; // Prop to handle pyramid layout centering
    contentScale?: 'normal' | 'medium' | 'large';
    layoutStyle?: React.CSSProperties;
}> = ({ diff, index, onSelect, activeInfo, onInfoToggle, isClosing, description, isPyramidTop, contentScale = 'normal', layoutStyle }) => {

    // Data Loading
    const completed = Storage.getCompletedCount(diff, 300);
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    const isPack3Unlocked = Storage.isPack3Unlocked(diff);

    let maxLevels = 100;
    if (isPack2Unlocked) maxLevels = 200;
    if (isPack3Unlocked) maxLevels = 300;

    const diffPoints = getDifficultyPoints(diff);

    // Animation Logic
    const delay = 100 + (index * 50); // Linear delay based on index is smoother

    const isInfoActive = activeInfo === diff;
    // If pyramid top, tooltip should default to right or calculate based on screen
    const isLeftColumn = isPyramidTop ? true : index % 2 === 0;

    // State to track if entry animation is done
    const [animating, setAnimating] = useState(true);
    useEffect(() => {
        const t = setTimeout(() => {
            setAnimating(false);
        }, delay + 600); // delay + animation duration (400ms) + buffer
        return () => clearTimeout(t);
    }, [delay]);

    // Z-Index Logic
    const baseZIndex = 30 - index; // Simple z-index stack
    const finalZIndex = isInfoActive ? 100 : baseZIndex;

    // Use animated counter hook
    const animatedCompleted = useAnimatedCounter(completed, 500);

    const progressPercent = Math.min((animatedCompleted / maxLevels) * 100, 100);

    // Default Style fallback (Grid Layout)
    const defaultStyle: React.CSSProperties = {
        width: '47.5%',
        aspectRatio: '1.55/1', 
    };

    const finalStyle = { ...defaultStyle, ...layoutStyle, zIndex: finalZIndex, animationDelay: `${delay}ms` };

    // Dynamic Scale classes
    const titleClass = contentScale === 'large' ? 'text-3xl mb-3' : (contentScale === 'medium' ? 'text-2xl mb-2' : 'text-lg mb-1');
    const iconSizeClass = contentScale === 'large' ? 'w-6 h-6' : (contentScale === 'medium' ? 'w-5 h-5' : 'w-3.5 h-3.5');
    const infoIconSizeClass = contentScale === 'large' ? 'w-8 h-8 -ml-1.5' : (contentScale === 'medium' ? 'w-7 h-7 -ml-1' : 'w-6 h-6 -ml-0.5');
    const infoIconInnerSize = contentScale === 'large' ? 'w-6 h-6' : (contentScale === 'medium' ? 'w-5 h-5' : 'w-4 h-4');
    const pointsTextClass = contentScale === 'large' ? 'text-xl' : (contentScale === 'medium' ? 'text-lg' : 'text-sm');
    const progressTextClass = contentScale === 'large' ? 'text-xl' : (contentScale === 'medium' ? 'text-lg' : 'text-sm');
    const progressBarHeight = contentScale === 'large' ? 'h-3' : (contentScale === 'medium' ? 'h-2.5' : 'h-1.5');
    const paddingClass = contentScale === 'large' ? 'p-6' : (contentScale === 'medium' ? 'p-5' : 'p-3.5');

    return (
        <button 
            onClick={() => onSelect(diff)} 
            style={finalStyle}
            className={`bg-t-surface ${paddingClass} rounded-2xl shadow-sm flex flex-col justify-between active:scale-95 transition-transform text-left relative group overflow-visible ${animating ? 'opacity-0 animate-slide-in-down' : 'opacity-100'}`}
        >
            {/* Header: Title & Points */}
            <div className="w-full flex justify-between items-start mb-1">
                <span className={`font-semibold text-stone-700 dark:text-stone-300 leading-none tracking-tight truncate mr-1 mt-0.5 ${titleClass}`}>{diff}</span>
                <div className="flex items-center gap-1 shrink-0">
                    <span className={`${pointsTextClass} font-bold text-t-primary opacity-80 leading-none`}>+{diffPoints}</span>
                    <Icons.Diamond className={`${iconSizeClass} text-blue-500 fill-current`} />
                </div>
            </div>

            {/* Middle: Info & Progress Numbers */}
            <div className="w-full flex justify-between items-end mb-2 mt-auto">
                {/* Info Icon */}
                <div className="relative z-50" onClick={(e) => e.stopPropagation()}>
                    <div 
                        role="button"
                        onClick={() => onInfoToggle(diff)}
                        className={`flex items-center justify-center cursor-pointer hover:bg-stone-100 dark:hover:bg-stone-700 rounded-full transition-colors ${infoIconSizeClass}`}
                    >
                        <Icons.Info className={`${infoIconInnerSize} transition-colors ${isInfoActive ? 'text-stone-800 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500'}`} />
                    </div>

                    {/* Tooltip */}
                    {isInfoActive && (
                        <div 
                            className={`absolute top-full mt-2 w-44 z-[60] cursor-default ${
                                isLeftColumn 
                                    ? '-left-2 origin-top-left' 
                                    : '-right-2 origin-top-right'
                            } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed border border-stone-400 dark:border-stone-500 shadow-lg">
                                {description}
                                <div className={`absolute -top-[6px] w-3 h-3 bg-white border-t border-l border-stone-400 dark:border-stone-500 transform rotate-45 ${
                                    isLeftColumn ? 'left-[14px]' : 'right-[14px]'
                                }`}></div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Progress Numbers (Animated) */}
                <span className={`${progressTextClass} text-stone-700 dark:text-stone-300 font-bold tracking-wide font-sans leading-none`}>
                    {animatedCompleted} / {maxLevels}
                </span>
            </div>

            {/* Bottom: Progress Bar (Animated) */}
            <div className={`w-full bg-t-surface-sec rounded-full overflow-hidden ${progressBarHeight}`}>
                <div 
                    className="h-full bg-loading-blue" 
                    style={{ 
                        width: `${progressPercent}%`,
                        transition: 'width 0.1s linear' 
                    }}
                ></div>
            </div>
        </button>
    );
};

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime,
    hiddenDifficulties = [] 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            // Change 24h countdown to static message
            setTimeLeft("Come back tomorrow!");
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150);
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    // Filter Difficulties
    const visibleDifficulties = Object.values(Difficulty).filter(d => !hiddenDifficulties.includes(d));
    const isOddCount = visibleDifficulties.length % 2 !== 0;
    const isVerticalStack = visibleDifficulties.length === 2;
    const isOneVisible = visibleDifficulties.length === 1;

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Content Container - removed overflow-y-auto, added overflow-hidden for non-scrollable */}
             <div className="flex-1 w-full overflow-hidden px-6 pb-6 pt-[70px] flex flex-col items-center min-h-0">

                  {/* Hero Section - Static */}
                  <div className="flex flex-col items-center mb-6 shrink-0">
                      <Logo size={70} className="mb-4 drop-shadow-xl" />
                      <h1 className="text-3xl font-semibold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Difficulty Header */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down shrink-0" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-semibold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid */}
                  <div className="w-full max-w-md flex flex-wrap justify-center gap-3 mb-8 shrink-0 min-h-[330px] content-center">
                      {visibleDifficulties.map((diff, index) => {
                          const descriptions = DIFFICULTY_DESCRIPTIONS[diff];
                          const currentIndex = infoIndices[diff] || 0;
                          const description = descriptions[currentIndex % descriptions.length];

                          // Pyramid Layout Logic:
                          // If odd total, the first item (index 0) becomes top of pyramid.
                          // Exclude single item case from pyramid top logic to avoid wrapper redundancy if not needed
                          const isPyramidTop = isOddCount && index === 0 && !isOneVisible;

                          // Determine dynamic sizing props
                          let contentScale: 'normal' | 'medium' | 'large' = 'normal';
                          let layoutStyle: React.CSSProperties = {};

                          if (isOneVisible) {
                              layoutStyle = { width: '62%', aspectRatio: '1.55/1' };
                              contentScale = 'normal';
                          } else if (isVerticalStack) {
                              layoutStyle = { width: '55%', aspectRatio: '1.55/1' };
                              contentScale = 'normal';
                          } else if (isPyramidTop) {
                              // Pyramid top (odd count) - Standard size but centered wrapper
                              layoutStyle = { width: '47.5%', aspectRatio: '1.55/1' };
                          }

                          if (isPyramidTop || isVerticalStack) {
                              // Wrap the top item (or all items if vertical stack) in a full-width container to force a new row and centering
                              return (
                                  <div key={diff} className="w-full flex justify-center">
                                      <DifficultyCard 
                                          diff={diff}
                                          index={index}
                                          onSelect={onDifficultySelect}
                                          activeInfo={activeInfo}
                                          onInfoToggle={handleInfoToggle}
                                          isClosing={isClosing && activeInfo === diff}
                                          description={description}
                                          isPyramidTop={true}
                                          contentScale={contentScale}
                                          layoutStyle={layoutStyle}
                                      />
                                  </div>
                              );
                          }

                          return (
                              <DifficultyCard 
                                  key={diff}
                                  diff={diff}
                                  index={index}
                                  onSelect={onDifficultySelect}
                                  activeInfo={activeInfo}
                                  onInfoToggle={handleInfoToggle}
                                  isClosing={isClosing && activeInfo === diff}
                                  description={description}
                                  contentScale={contentScale}
                                  layoutStyle={layoutStyle}
                              />
                          );
                      })}
                  </div>

                  {/* Footer Actions */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down" 
                        style={{ animationDelay: '250ms' }}
                      >
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStore(); }} 
                            style={{ background: 'linear-gradient(135deg, #E8BA6E 0%, #B78B4D 100%)' }}
                            className="w-full p-4 text-[#3f2e18] rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition relative"
                          >
                              <Icons.Store className="w-5 h-5" /> <span className="font-semibold tracking-wide">Store</span>
                          </button>

                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} 
                            style={{ background: 'linear-gradient(135deg, #ffffff 0%, #f1f5f9 50%, #cbd5e1 100%)' }}
                            className="w-full p-4 text-slate-800 rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition-all relative overflow-hidden"
                          >
                              <div className="absolute bottom-0 inset-x-0 h-12 bg-gradient-to-t from-blue-100/30 to-transparent pointer-events-none" />
                              <div className="absolute inset-0 -translate-x-full animate-[shimmer_4s_infinite] bg-gradient-to-r from-transparent via-white/80 to-transparent skew-x-[-20deg] pointer-events-none" />
                              <span className="font-bold tracking-wide relative z-10 text-slate-700">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10 drop-shadow-sm" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus */}
                      <div 
                        className="grid grid-cols-2 gap-3 opacity-0 animate-slide-in-down"
                        style={{ animationDelay: '300ms' }}
                      >
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStats(); }} 
                            style={{ background: 'linear-gradient(135deg, #B8D3F5 0%, #79A6E3 100%)' }}
                            className="w-full p-4 text-[#102a43] rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition"
                          >
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-semibold tracking-wide">Stats</span>
                          </button>

                          <button 
                              onClick={(e) => { e.stopPropagation(); onClaimBonus(); }}
                              disabled={!!timeLeft}
                              style={!timeLeft ? { background: 'linear-gradient(135deg, #B8DBBE 0%, #8CB794 100%)' } : undefined}
                              className={`w-full p-4 rounded-2xl flex items-center justify-center gap-2 transition overflow-hidden relative ${
                                  !!timeLeft 
                                  ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed shadow-sm' 
                                  : 'text-[#163c20] shadow-[0_2px_8px_rgba(0,0,0,0.08)] active:scale-95'
                              }`}
                          >
                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-4 h-4" />
                                      <span className="font-semibold text-xs uppercase tracking-wider">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-semibold tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>

                  {/* Utility Row (Points + Settings) */}
                  <div 
                    className="w-full max-w-md flex items-center justify-center gap-3 mt-6 mb-2 opacity-0 animate-slide-in-down shrink-0" 
                    style={{ animationDelay: '350ms' }}
                  >
                      <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm">
                          <span className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5">{points}</span>
                          <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                      </div>

                      <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenSettings(); }} className="p-1.5 bg-t-surface rounded-full shadow-sm hover:bg-stone-100 dark:hover:bg-stone-800 transition active:scale-95 text-t-icon">
                          <Icons.Settings className="w-5 h-5" />
                      </button>
                  </div>

                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Difficulty, AppSettings, DiamondOffer, StoredData } from './types';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { SudokuGame } from './components/SudokuGame';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';
import { SettingsModal, NotEnoughPointsModal, PurchaseModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS, getPackCost } from './utils/constants';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'store' | 'diamondShop' | 'stats';

export const App: React.FC = () => {
    const [screen, setScreen] = useState<Screen>('splash');

    // Data State
    const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
    const [points, setPoints] = useState<number>(0);
    const [nextBonusClaimTime, setNextBonusClaimTime] = useState<number>(0);
    const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>([]);
    const [selectedBackground, setSelectedBackground] = useState<string>('bg-default');
    const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>([]);
    const [selectedNumberColor, setSelectedNumberColor] = useState<string>('num-default');
    const [purchasedSkills, setPurchasedSkills] = useState<string[]>([]);
    const [enabledSkills, setEnabledSkills] = useState<string[]>([]);
    const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>([]);
    const [selectedSoundPack, setSelectedSoundPack] = useState<string>('snd-zen');
    const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>([]);
    const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>([]);
    const [starterPackPurchased, setStarterPackPurchased] = useState(false);
    const [purchasedBundles, setPurchasedBundles] = useState<string[]>([]);

    // Navigation State
    const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty>(Difficulty.Normal);
    const [selectedLevelId, setSelectedLevelId] = useState<number>(1);

    // Modal State
    const [showSettings, setShowSettings] = useState(false);
    const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
    const [showAd, setShowAd] = useState(false);

    const [purchaseItem, setPurchaseItem] = useState<{item: any, type: 'bg' | 'num' | 'skill' | 'sound' | 'pack2' | 'pack3'} | null>(null);
    const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

    // Initialization
    useEffect(() => {
        const init = async () => {
            const data = await Storage.initializeNative() || Storage.getStoredData();

            setSettings(data.settings);
            setPoints(data.points);
            setNextBonusClaimTime(data.nextBonusClaimTime || 0);
            setPurchasedBackgrounds(data.purchasedBackgrounds);
            setSelectedBackground(data.selectedBackground || 'bg-default');
            setPurchasedNumberColors(data.purchasedNumberColors);
            setSelectedNumberColor(data.selectedNumberColor);
            setPurchasedSkills(data.purchasedSkills);
            setEnabledSkills(data.enabledSkills || []);
            setPurchasedSoundPacks(data.purchasedSoundPacks || ['snd-zen']);
            setSelectedSoundPack(data.selectedSoundPack || 'snd-zen');
            setUnlockedPacks2(data.unlockedPack2 || []);
            setUnlockedPacks3(data.unlockedPack3 || []);
            setStarterPackPurchased(!!data.starterPackPurchased);
            setPurchasedBundles(data.purchasedBundles || []);

            sounds.setEnabled(data.settings.sound);
            sounds.setVibrationEnabled(data.settings.vibration);
            sounds.setProfile(data.selectedSoundPack || 'snd-zen');

            // Apply theme
            applyTheme(data.settings.appearance);

            setTimeout(() => {
                setScreen('difficulty');
            }, 2500);
        };
        init();
    }, []);

    const applyTheme = (appearance: 'system' | 'light' | 'dark') => {
        const root = window.document.documentElement;
        root.classList.remove('light', 'dark');
        if (appearance === 'system') {
            if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
                root.classList.add('dark');
            } else {
                root.classList.add('light');
            }
        } else {
            root.classList.add(appearance);
        }
    };

    // Helper to refresh data from storage
    const refreshData = () => {
        const data = Storage.getStoredData();
        setSettings(data.settings);
        setPoints(data.points);
        setPurchasedBackgrounds(data.purchasedBackgrounds);
        setSelectedBackground(data.selectedBackground || 'bg-default');
        setPurchasedNumberColors(data.purchasedNumberColors);
        setSelectedNumberColor(data.selectedNumberColor);
        setPurchasedSkills(data.purchasedSkills);
        setEnabledSkills(data.enabledSkills || []);
        setPurchasedSoundPacks(data.purchasedSoundPacks || ['snd-zen']);
        setSelectedSoundPack(data.selectedSoundPack || 'snd-zen');
        setUnlockedPacks2(data.unlockedPack2 || []);
        setUnlockedPacks3(data.unlockedPack3 || []);
        setStarterPackPurchased(!!data.starterPackPurchased);
        setPurchasedBundles(data.purchasedBundles || []);

        sounds.setEnabled(data.settings.sound);
        sounds.setVibrationEnabled(data.settings.vibration);
        sounds.setProfile(data.selectedSoundPack || 'snd-zen');
    };

    const handleEarnPoints = (amount: number) => {
        Storage.addPoints(amount);
        refreshData();
    };

    const handleClaimBonus = () => {
        const now = Date.now();
        if (now < nextBonusClaimTime) return;
        sounds.playWin();

        const nextDate = new Date();
        nextDate.setDate(nextDate.getDate() + 1);
        nextDate.setHours(0, 0, 0, 0);
        const nextTime = nextDate.getTime();

        Storage.setNextBonusClaimTime(nextTime);
        handleEarnPoints(10);
        setNextBonusClaimTime(nextTime); // Update local state immediately
    };

    const handlePurchaseItem = () => {
        if (!purchaseItem) return;
        const { item, type } = purchaseItem;

        let success = false;
        if (type === 'bg') success = Storage.purchaseBackground(item.id, item.cost);
        else if (type === 'num') success = Storage.purchaseNumberColor(item.id, item.cost);
        else if (type === 'skill') success = Storage.purchaseSkill(item.id, item.cost);
        else if (type === 'sound') success = Storage.purchaseSoundPack(item.id, item.cost);
        else if (type === 'pack2') success = Storage.unlockPack2(selectedDifficulty, item.cost);
        else if (type === 'pack3') success = Storage.unlockPack3(selectedDifficulty, item.cost);

        if (success) {
            sounds.playWin();
            refreshData();
            setPurchaseItem(null);
        } else {
            setPurchaseItem(null);
            setShowNotEnoughPoints(true);
        }
    };

    const handleDiamondPurchase = (offer: DiamondOffer) => {
        // Mock purchase logic
        if (offer.type === 'starter') {
            Storage.setStarterPackPurchased();
            Storage.purchaseSkill('skill-auto', 0);
            Storage.purchaseSkill('skill-scan', 0);
            Storage.purchaseNumberColor('num-purple', 0);
            Storage.purchaseNumberColor('num-teal', 0);
        } else if (offer.type === 'bundle') {
            Storage.purchaseBundle(offer.id);
            if (offer.id === 'bundle_skill') {
                Storage.purchaseSkill('skill-auto', 0);
                Storage.purchaseSkill('skill-scan', 0);
            } else if (offer.id === 'bundle_cosmetic') {
                STATIC_BACKGROUNDS.forEach(b => Storage.purchaseBackground(b.id, 0));
                DYNAMIC_BACKGROUNDS.forEach(b => Storage.purchaseBackground(b.id, 0));
            } else if (offer.id === 'bundle_pro') {
                SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
                Storage.purchaseNumberColor('num-rgb', 0);
            }
        }

        Storage.addPoints(offer.diamonds);
        refreshData();
        setPaymentOffer(null);
    };

    const handleWatchAd = () => {
        setShowAd(true);
        setTimeout(() => {
            setShowAd(false);
            handleEarnPoints(25);
            sounds.playWin();
        }, 3000);
    };

    const handleToggleSetting = (key: keyof AppSettings) => {
        sounds.playClick();
        const newSettings = { ...settings, [key]: !settings[key] };
        setSettings(newSettings);
        Storage.saveSettings(newSettings);

        if (key === 'sound') sounds.setEnabled(newSettings.sound);
        if (key === 'vibration') sounds.setVibrationEnabled(newSettings.vibration);
    };

    const handleToggleDifficulty = (diff: Difficulty) => {
        sounds.playClick();
        let current = settings.hiddenDifficulties || [];
        if (current.includes(diff)) {
            current = current.filter(d => d !== diff);
        } else {
            // Ensure at least one remains visible
            if (current.length < Object.values(Difficulty).length - 1) {
                current.push(diff);
            }
        }
        const newSettings = { ...settings, hiddenDifficulties: current };
        setSettings(newSettings);
        Storage.saveSettings(newSettings);
    };

    const handleSetAppearance = (val: 'system' | 'light' | 'dark') => {
        const newSettings = { ...settings, appearance: val };
        setSettings(newSettings);
        Storage.saveSettings(newSettings);
        applyTheme(val);
    };

    // Background Class resolver
    const getBgClass = () => {
        const bg = [...STATIC_BACKGROUNDS, ...DYNAMIC_BACKGROUNDS].find(b => b.id === selectedBackground);
        return bg ? bg.class : 'bg-paper dark:bg-stone-900';
    };

    const getNumberColorClass = () => {
        const num = NUMBER_COLORS.find(n => n.id === selectedNumberColor);
        return num ? num.class : 'text-blue-600';
    };

    return (
        <div className={`w-full h-full flex flex-col items-center justify-center overflow-hidden transition-colors duration-500 ${getBgClass()}`}>

            {screen === 'splash' && <SplashScreen />}

            {screen === 'difficulty' && (
                <DifficultyScreen 
                    points={points}
                    onDifficultySelect={(diff) => {
                        sounds.playClick();
                        setSelectedDifficulty(diff);
                        setScreen('levels');
                    }}
                    onOpenSettings={() => setShowSettings(true)}
                    onOpenStore={() => setScreen('store')}
                    onOpenDiamondShop={() => setScreen('diamondShop')}
                    onClaimBonus={handleClaimBonus}
                    onOpenStats={() => setScreen('stats')}
                    nextBonusClaimTime={nextBonusClaimTime}
                    hiddenDifficulties={settings.hiddenDifficulties}
                />
            )}

            {screen === 'levels' && (
                <LevelsScreen 
                    difficulty={selectedDifficulty}
                    points={points}
                    unlockedPacks2={unlockedPacks2}
                    unlockedPacks3={unlockedPacks3}
                    onBack={() => {
                        sounds.playClick();
                        setScreen('difficulty');
                    }}
                    onLevelSelect={(id) => {
                        sounds.playClick();
                        setSelectedLevelId(id);
                        setScreen('game');
                    }}
                    onOpenSettings={() => setShowSettings(true)}
                    onUnlockPack2={() => setPurchaseItem({ item: { id: 'pack2', name: 'Level Pack 2 (101-200)', cost: getPackCost(selectedDifficulty, 2) }, type: 'pack2' })}
                    onUnlockPack3={() => setPurchaseItem({ item: { id: 'pack3', name: 'Level Pack 3 (201-300)', cost: getPackCost(selectedDifficulty, 3) }, type: 'pack3' })}
                />
            )}

            {screen === 'game' && (
                <SudokuGame 
                    difficulty={selectedDifficulty}
                    levelId={selectedLevelId}
                    onBack={() => {
                        sounds.playClick();
                        setScreen('levels');
                    }}
                    onReturnToMenu={() => {
                        sounds.playClick();
                        setScreen('difficulty');
                    }}
                    onComplete={() => refreshData()}
                    onSettingsOpen={() => setShowSettings(true)}
                    settings={settings}
                    onEarnPoints={handleEarnPoints}
                    currentPoints={points}
                    isSettingsOpen={showSettings || !!purchaseItem || !!paymentOffer || showNotEnoughPoints}
                    backgroundClass={getBgClass()}
                    numberColor={getNumberColorClass()}
                    purchasedSkills={purchasedSkills}
                />
            )}

            {screen === 'store' && (
                <StoreScreen 
                    points={points}
                    onBack={() => {
                        sounds.playClick();
                        setScreen('difficulty');
                    }}
                    purchasedSkills={purchasedSkills}
                    enabledSkills={enabledSkills}
                    purchasedBackgrounds={purchasedBackgrounds}
                    purchasedNumberColors={purchasedNumberColors}
                    purchasedSoundPacks={purchasedSoundPacks}
                    selectedBackgroundId={selectedBackground}
                    selectedNumberColorId={selectedNumberColor}
                    selectedSoundPackId={selectedSoundPack}
                    onPurchase={(item, type) => setPurchaseItem({item, type})}
                    onSelectBackground={(id) => {
                        sounds.playClick();
                        Storage.selectBackground(id);
                        refreshData();
                    }}
                    onSelectNumberColor={(id) => {
                        sounds.playClick();
                        Storage.selectNumberColor(id);
                        refreshData();
                    }}
                    onSelectSoundPack={(id) => {
                        sounds.playClick();
                        Storage.selectSoundPack(id);
                        refreshData();
                    }}
                    onToggleSkill={(id) => {
                        Storage.toggleSkillEnabled(id);
                        refreshData();
                    }}
                />
            )}

            {screen === 'diamondShop' && (
                <DiamondShopScreen 
                    points={points}
                    onBack={() => {
                        sounds.playClick();
                        setScreen('difficulty');
                    }}
                    onWatchAd={handleWatchAd}
                    onBuyOffer={(offer) => setPaymentOffer(offer)}
                    starterPackPurchased={starterPackPurchased}
                    purchasedBundles={purchasedBundles}
                />
            )}

            {screen === 'stats' && (
                <StatsScreen 
                    onBack={() => {
                        sounds.playClick();
                        setScreen('difficulty');
                    }}
                />
            )}

            {/* Overlays / Modals */}
            {showSettings && (
                <SettingsModal 
                    settings={settings}
                    onToggle={handleToggleSetting}
                    onToggleDifficulty={handleToggleDifficulty}
                    onSetAppearance={handleSetAppearance}
                    onReset={() => {
                        if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
                            Storage.resetAllData();
                            window.location.reload();
                        }
                    }}
                    onClose={() => setShowSettings(false)}
                    onAddDevPoints={() => {
                        handleEarnPoints(5000);
                        sounds.playWin();
                    }}
                />
            )}

            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)}
                    onGetMore={() => {
                        setShowNotEnoughPoints(false);
                        setScreen('diamondShop');
                    }}
                    onGoPlay={() => {
                        setShowNotEnoughPoints(false);
                        setScreen('levels');
                    }}
                />
            )}

            {purchaseItem && (
                <PurchaseModal 
                    item={purchaseItem.item}
                    onConfirm={handlePurchaseItem}
                    onCancel={() => setPurchaseItem(null)}
                />
            )}

            {paymentOffer && (
                <PaymentModal 
                    offer={paymentOffer}
                    onComplete={() => handleDiamondPurchase(paymentOffer)}
                    onCancel={() => setPaymentOffer(null)}
                />
            )}

            {showAd && <AdOverlay />}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS, SKILLS } from './utils/constants';
import { motion, AnimatePresence } from 'framer-motion';

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [purchasedBundles, setPurchasedBundles] = useState<string[]>(Storage.getPurchasedBundles());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Initialize Native Storage
  useEffect(() => {
    const initStorage = async () => {
        const nativeData = await Storage.initializeNative();
        if (nativeData) {
            setPoints(nativeData.points);
            setSettings(nativeData.settings);
            setPurchasedBackgrounds(nativeData.purchasedBackgrounds);
            setPurchasedNumberColors(nativeData.purchasedNumberColors);
            setPurchasedSoundPacks(nativeData.purchasedSoundPacks || ['snd-zen']);
            setSelectedSoundPackId(nativeData.selectedSoundPack || 'snd-zen');
            setPurchasedSkills(nativeData.purchasedSkills);
            setEnabledSkills(nativeData.enabledSkills || [...nativeData.purchasedSkills]);
            setPurchasedBundles(nativeData.purchasedBundles || []);
            setStarterPackPurchased(nativeData.starterPackPurchased || false);

            const isDark = nativeData.settings.appearance === 'dark' || (nativeData.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
            if (isDark) document.documentElement.classList.add('dark');
            else document.documentElement.classList.remove('dark');
        }
    };
    initStorage();
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setPurchasedBundles(Storage.getPurchasedBundles());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const handleToggleDifficultyVisibility = (diff: Difficulty) => {
      sounds.playTap();
      const currentHidden = settings.hiddenDifficulties || [];
      let newHidden: Difficulty[];

      if (currentHidden.includes(diff)) {
          newHidden = currentHidden.filter(d => d !== diff);
      } else {
          // Prevent hiding the last visible difficulty
          const allDiffs = Object.values(Difficulty);
          if (allDiffs.length - currentHidden.length <= 1) {
             // Maybe play error sound?
             return; 
          }
          newHidden = [...currentHidden, diff];
      }

      const newSettings = { ...settings, hiddenDifficulties: newHidden };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This cannot be undone.")) {
          Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = () => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();

    // Set next claim time to next midnight (00:00:00)
    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + 1);
    nextDate.setHours(0, 0, 0, 0);
    const nextTime = nextDate.getTime();

    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      sounds.playPop();
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        setIsWatchingAd(true);
        setTimeout(() => {
            handleEarnPoints(25);
            setIsWatchingAd(false);
            sounds.playWin();
        }, 5000);
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.type === 'bundle' && purchasedBundles.includes(offer.id)) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;
      handleEarnPoints(offer.diamonds);
      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseSkill('skill-scan', 0);
          Storage.purchaseNumberColor('num-purple', 0);
          Storage.purchaseNumberColor('num-teal', 0);
      } else if (offer.type === 'bundle') {
          Storage.purchaseBundle(offer.id);
          setPurchasedBundles([...purchasedBundles, offer.id]);
          if (offer.id === 'bundle_skill') {
              Storage.purchaseSkill('skill-auto', 0);
              Storage.purchaseSkill('skill-scan', 0);
          } else if (offer.id === 'bundle_cosmetic') {
              ALL_BACKGROUNDS.forEach(bg => Storage.purchaseBackground(bg.id, 0));
          } else if (offer.id === 'bundle_pro') {
              SKILLS.forEach(s => Storage.purchaseSkill(s.id, 0));
              Storage.purchaseNumberColor('num-rgb', 0);
          }
      }
      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleAddDevPoints = () => {
      handleEarnPoints(5000);
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 

  if (selectedBackgroundId) {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      if (bg) {
          activeBackgroundClass = bg.class;
      }
  }

  // NOTE: Splash screen override removed to allow global background selection to persist on all screens.

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Slide" Transition
  // Using 100% width slide to prevent cuts and ensure screens move completely off-view
  const variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Background Layer (Persistent) */}
          <div 
            className={`fixed inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
            style={{ width: '100%', height: '100%' }}
          />
          <div 
            className="fixed inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
            style={{ opacity: overlayOpacity }} 
          />

          {/* Screen Content Layer (Animated) */}
          <div 
             className="relative z-10 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden"
             style={{ paddingTop: 'env(safe-area-inset-top)' }}
          >
            <AnimatePresence custom={direction} initial={false}>
                <motion.div
                    key={screen}
                    custom={direction}
                    variants={variants}
                    initial="initial"
                    animate="animate"
                    exit="exit"
                    className="w-full h-full absolute inset-0 flex flex-col bg-transparent"
                    style={{ pointerEvents: 'auto' }}
                >
                    {screen === 'splash' && <SplashScreen />}

                    {screen === 'difficulty' && (
                        <DifficultyScreen 
                            points={points}
                            onDifficultySelect={handleDifficultySelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onOpenStore={() => navigate('store', 'forward')}
                            onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                            onClaimBonus={handleClaimBonus}
                            onOpenStats={() => navigate('stats', 'forward')}
                            nextBonusClaimTime={nextBonusClaimTime}
                            hiddenDifficulties={settings.hiddenDifficulties}
                        />
                    )}

                    {screen === 'diamondShop' && (
                        <DiamondShopScreen 
                            points={points}
                            onBack={handleDiamondShopBack}
                            onWatchAd={handleWatchAd}
                            onBuyOffer={handleBuyOffer}
                            starterPackPurchased={starterPackPurchased}
                            purchasedBundles={purchasedBundles}
                        />
                    )}

                    {screen === 'stats' && (
                        <StatsScreen 
                            onBack={handleStatsBack}
                        />
                    )}

                    {screen === 'levels' && selectedDifficulty && (
                        <LevelsScreen 
                            difficulty={selectedDifficulty}
                            points={points}
                            unlockedPacks2={unlockedPacks2}
                            unlockedPacks3={unlockedPacks3}
                            onBack={handleLevelBack}
                            onLevelSelect={handleLevelSelect}
                            onOpenSettings={() => setShowSettings(true)}
                            onUnlockPack2={handleUnlockPack2}
                            onUnlockPack3={handleUnlockPack3}
                        />
                    )}

                    {screen === 'store' && (
                        <StoreScreen 
                            points={points}
                            onBack={handleStoreBack}
                            purchasedSkills={purchasedSkills}
                            enabledSkills={enabledSkills}
                            purchasedBackgrounds={purchasedBackgrounds}
                            purchasedNumberColors={purchasedNumberColors}
                            purchasedSoundPacks={purchasedSoundPacks}
                            selectedBackgroundId={selectedBackgroundId}
                            selectedNumberColorId={selectedNumberColorId}
                            selectedSoundPackId={selectedSoundPackId}
                            onPurchase={initiatePurchase}
                            onSelectBackground={handleSelectBackground}
                            onSelectNumberColor={handleSelectNumberColor}
                            onSelectSoundPack={handleSelectSoundPack}
                            onToggleSkill={handleToggleSkill}
                        />
                    )}

                    {screen === 'game' && selectedDifficulty && selectedLevel && (
                        <SudokuGame
                            difficulty={selectedDifficulty}
                            levelId={selectedLevel}
                            onBack={handleGameBack}
                            onReturnToMenu={handleReturnToMenu}
                            onComplete={() => {
                                setPoints(Storage.getPoints());
                            }}
                            onSettingsOpen={() => setShowSettings(true)}
                            settings={settings}
                            onEarnPoints={handleEarnPoints}
                            currentPoints={points}
                            isSettingsOpen={showSettings}
                            backgroundClass={activeBackgroundClass}
                            numberColor={numberColorClass}
                            purchasedSkills={enabledSkills} // Pass only enabled skills to game
                        />
                    )}
                </motion.div>
            </AnimatePresence>

            {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
            {showSettings && (
                <SettingsModal 
                    settings={settings} 
                    onToggle={toggleSetting} 
                    onToggleDifficulty={handleToggleDifficultyVisibility}
                    onSetAppearance={setAppearance}
                    onReset={resetProgress}
                    onClose={() => setShowSettings(false)} 
                    onAddDevPoints={handleAddDevPoints}
                />
            )}
            {replayLevelId !== null && selectedDifficulty && (
                <ReplayModal 
                    levelId={replayLevelId}
                    onConfirm={confirmReplay}
                    onCancel={() => setReplayLevelId(null)}
                />
            )}
            {purchaseCandidate && (
                <PurchaseModal 
                    item={purchaseCandidate} 
                    onConfirm={confirmPurchase} 
                    onCancel={() => setPurchaseCandidate(null)} 
                />
            )}
            {paymentOffer && (
                <PaymentModal
                    offer={paymentOffer}
                    onComplete={finalizeRealMoneyPurchase}
                    onCancel={() => setPaymentOffer(null)}
                />
            )}
            {showNotEnoughPoints && (
                <NotEnoughPointsModal 
                    onClose={() => setShowNotEnoughPoints(false)} 
                    onGetMore={handleNavigateToShop} 
                    onGoPlay={handleGoPlay} 
                />
            )}
            {isWatchingAd && <AdOverlay />}
          </div>
      </>
  );
}

import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { Logo } from '../ui/Logo';
