interface SoundProfile {
    id: string;
    type: 'sine' | 'square' | 'triangle' | 'sawtooth';
    uiClickFreq: number;
    uiTapFreq: number;
    numberFreqs: number[];
    popFreq: number;
    duration: number; // Base duration in seconds
    volumeScale: number;
    pitchDrop?: boolean;
    pitchRise?: boolean; // New prop for rubber
}

