    },
    'snd-water': {
        id: 'snd-water',
        type: 'sine',
        uiClickFreq: 900,
        uiTapFreq: 800,
        numberFreqs: [600, 650, 700, 750, 800, 850, 900, 950, 1000],
        popFreq: 500,
        duration: 0.12, 
        volumeScale: 0.8,
        pitchDrop: true 
    },
    'snd-piano': {
        id: 'snd-piano',
        type: 'triangle', 
        uiClickFreq: 1046, // Fallback freq
        uiTapFreq: 523, // C5
        tapFreqs: [523.25, 587.33, 659.25, 783.99, 880.00], // C Major Pentatonic (C5, D5, E5, G5, A5)
        // Pentatonic Major Scale: C4, D4, E4, G4, A4, C5, D5, E5, G5
        numberFreqs: [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99],
        popFreq: 196, // G3
